/**
 * PLAN.md §5.2: primary keys are UUIDv7 generated by the database (`DEFAULT uuidv7()`),
 * which is built in from Postgres 18. That makes 18 a stated deployment requirement rather
 * than a silent assumption — and a stated requirement deserves a check that says so, since
 * the alternative is a first migration failing with `function uuidv7() does not exist`,
 * which reads as a broken migration rather than a wrong server.
 */

export const MINIMUM_POSTGRES_MAJOR = 18;

export class UnsupportedPostgresError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "UnsupportedPostgresError";
	}
}

/**
 * @param serverVersionNum Postgres' `server_version_num` — 180002 for 18.2.
 * @throws {UnsupportedPostgresError} below {@link MINIMUM_POSTGRES_MAJOR}.
 */
export function assertSupportedPostgres(serverVersionNum: number): void {
	if (!Number.isFinite(serverVersionNum) || serverVersionNum <= 0) {
		throw new UnsupportedPostgresError(
			`Could not read the Postgres version (got ${serverVersionNum}). ` +
				`Postgres ${MINIMUM_POSTGRES_MAJOR} or later is required for uuidv7().`,
		);
	}

	const major = Math.floor(serverVersionNum / 10_000);

	if (major < MINIMUM_POSTGRES_MAJOR) {
		throw new UnsupportedPostgresError(
			`Postgres ${MINIMUM_POSTGRES_MAJOR} or later is required — this server is ${major}. ` +
				`Primary keys are generated with the built-in uuidv7(), which earlier versions do not have.`,
		);
	}
}
